/**
 * Route selection for the mobile layout audit.
 *
 * Tier A is a fixed list of page archetypes — those ARE the templates, so
 * there is nothing to derive. Tier B is scored from the generated content
 * corpus, because that corpus is regenerated by build-content-data.mjs and
 * the worst case moves: a hardcoded list certifies today's 535 pages, a
 * scored list re-certifies whatever the generator emits next month.
 */

import { readFileSync } from "node:fs";

const CONTENT_DATA = "src/site/generated/content-data.ts";

/** One entry per distinct page template / visual archetype. */
export const ARCHETYPE_ROUTES = [
  { path: "/", archetype: "home" },
  { path: "/get", archetype: "get-app (hero + QR)" },
  { path: "/privacy", archetype: "static-knowledge" },
  { path: "/terms", archetype: "static-knowledge" },
  { path: "/support", archetype: "static-knowledge" },
  { path: "/privacy-features", archetype: "static-knowledge" },
  // Cloudflare Pages serves the real 404 status; `vite preview`'s SPA fallback
  // answers 200 for the same URL, so the expectation has to be declared rather
  // than inferred from whichever origin is being audited.
  { path: "/this-route-does-not-exist", archetype: "404", expectedStatus: 404 },
  { path: "/resources", archetype: "hub-pillar" },
  { path: "/compare", archetype: "hub-pillar" },
  { path: "/resources/guides", archetype: "hub-pillar" },
  { path: "/resources/health", archetype: "hub-pillar" },
  { path: "/free", archetype: "hub-pillar" },
  { path: "/tools/quiz", archetype: "hub-pillar" },
  { path: "/period-tracker-privacy", archetype: "hub-state-tier" },
  { path: "/compare/versus", archetype: "hub-plain" },
  { path: "/compare/alternatives", archetype: "hub-plain" },
  { path: "/compare/pricing", archetype: "hub-plain" },
  { path: "/resources/best", archetype: "hub-plain" },
  { path: "/resources/privacy-in-practice", archetype: "hub-plain (97 entries — densest)" },
  { path: "/app-guides", archetype: "hub-plain" },
];

/** Optional frontmatter blocks that each add a distinct rendered section. */
const CHROME_BLOCKS = [
  "tools",
  "tiers",
  "hiddenCosts",
  "proscons",
  "expertQuotes",
  "relevantLaws",
  "definitions",
  "pricingStats",
  "sources",
  "faqs",
  "keyFacts",
  "answers",
  "steps",
];

export function loadContentEntries(root = process.cwd()) {
  const src = readFileSync(`${root}/${CONTENT_DATA}`, "utf8");
  const start = src.indexOf("[");
  const end = src.lastIndexOf("] as const;");
  if (start === -1 || end === -1) {
    throw new Error(
      `Could not parse ${CONTENT_DATA}. build-content-data.mjs may have changed its output format.`,
    );
  }
  const entries = JSON.parse(src.slice(start, end + 1));

  /* Fail loud rather than silently auditing zero pages. The floor is a
     parse-sanity check, not a content-inventory assertion — it deliberately
     sits well below the current corpus (535) so a legitimate consolidation
     does not hard-fail the gate with a misleading "parse error". The last one
     took /free/ from 348 pages to 35, and a floor of 500 would have broken
     this on a change that was entirely intentional. */
  if (entries.length < 100) {
    throw new Error(
      `Expected >=100 content entries, parsed ${entries.length}. ` +
        `Either ${CONTENT_DATA} changed format, or the corpus shrank far enough that this floor needs revisiting.`,
    );
  }
  return entries;
}

/** Widest markdown table in a body, measured in columns. */
function maxMarkdownTableColumns(body) {
  if (!body) return 0;
  let max = 0;
  for (const line of String(body).split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("|")) continue;
    const cols = trimmed.split("|").filter((c) => c.trim().length > 0).length;
    if (cols > max) max = cols;
  }
  return max;
}

function longestToken(entry) {
  const haystack = [entry.title, entry.state, entry.seoTitle]
    .filter(Boolean)
    .concat(
      String(entry.body || "")
        .split("\n")
        .filter((l) => l.trim().startsWith("#")),
    )
    .join(" ");
  let max = 0;
  for (const token of haystack.split(/\s+/)) {
    const clean = token.replace(/[^\p{L}\p{N}-]/gu, "");
    if (clean.length > max) max = clean.length;
  }
  return max;
}

function chromeRichness(entry) {
  return CHROME_BLOCKS.reduce((n, key) => {
    const v = entry[key];
    if (!v) return n;
    if (Array.isArray(v)) return v.length ? n + 1 : n;
    if (typeof v === "object") return Object.keys(v).length ? n + 1 : n;
    return n + 1;
  }, 0);
}

/**
 * Three orthogonal risk axes, deliberately not blended into one score — a
 * blended score picks the same page three times and misses two failure modes.
 */
const AXES = [
  {
    id: "widest-table",
    why: "overflow + the min-width:40rem scroller",
    score: (e) => Math.max((e.tableData?.columns?.length ?? 0), maxMarkdownTableColumns(e.body)),
    label: (v) => `widest-table:${v}cols`,
  },
  {
    id: "longest-token",
    why: "unbreakable words against a 40px display-serif hero",
    score: longestToken,
    label: (v) => `longest-token:${v}chars`,
  },
  {
    id: "richest-chrome",
    why: "tallest page, most structurally varied section mix",
    score: chromeRichness,
    label: (v) => `chrome-blocks:${v}`,
  },
];

/**
 * Pick worst-case content instances per collection, plus a median control.
 * The control distinguishes "only the outlier is broken" from "every page in
 * this collection is broken" — without it those look identical.
 */
export function selectContentRoutes(entries, { perCollection = 3 } = {}) {
  const byCollection = new Map();
  for (const entry of entries) {
    if (!byCollection.has(entry.collection)) byCollection.set(entry.collection, []);
    byCollection.get(entry.collection).push(entry);
  }

  const selected = new Map();
  const note = (entry, reason) => {
    const existing = selected.get(entry.routePath);
    if (existing) {
      if (!existing.selectedBecause.includes(reason)) existing.selectedBecause.push(reason);
      return;
    }
    selected.set(entry.routePath, {
      path: entry.routePath,
      archetype: `content:${entry.collection}`,
      collection: entry.collection,
      selectedBecause: [reason, `collection:${entry.collection}`],
    });
  };

  for (const [collection, list] of byCollection) {
    const picks = [];
    for (const axis of AXES) {
      let best = null;
      let bestScore = -1;
      for (const entry of list) {
        const score = axis.score(entry);
        if (score > bestScore) {
          bestScore = score;
          best = entry;
        }
      }
      if (best && bestScore > 0 && !picks.includes(best)) {
        picks.push(best);
        note(best, axis.label(bestScore));
      }
      if (picks.length >= perCollection) break;
    }

    // Median control for the larger collections.
    if (list.length >= 25) {
      const sorted = [...list].sort((a, b) => a.slug.localeCompare(b.slug));
      const mid = sorted[Math.floor(sorted.length / 2)];
      if (!picks.includes(mid)) note(mid, "median-control");
    }
  }

  return [...selected.values()];
}

export function buildRouteList(root = process.cwd(), { archetypesOnly = false } = {}) {
  const archetypes = ARCHETYPE_ROUTES.map((r) => ({
    ...r,
    selectedBecause: ["archetype"],
  }));
  if (archetypesOnly) return archetypes;
  const entries = loadContentEntries(root);
  return archetypes.concat(selectContentRoutes(entries));
}

export function slugForPath(pathname) {
  return pathname.replace(/^\//, "").replace(/\//g, "__") || "_root";
}
